-- wave-canggu-2026-10-08: 357 field(s) in one DO block, one UPDATE per column.
-- Each UPDATE must change exactly the number of rows it lists; if one does not, the whole block rolls back.
-- Generated 2026-10-08 by scripts/copy/build-copy-sql.mjs. Guards: md5 of the current text; every literal is ASCII.
do $apply$
declare n int;
begin
  update venues v set why_its_here = d.val
  from (values
    ('12-urban-cafe-breakfast-and-dinner-movie-night-cocktail-bar-canggu', 'ea13656751b5d2940200b867ae2c2cf7', 'A cafe and cocktail bar on Jalan Pantai Batu Mejan, open 8am to midnight daily. The main menu goes from pasta and risotto to schnitzel and seafood, with a rib eye steak. Brunch, the bar and wine cocktails have their own menus. Book through the site or Chope.'),
    ('7am-bakers-umalas', '740ebfabb748362de4a6b060206d19be', 'On Jalan Bumbak Dauh, 7AM Bakers runs its Umalas outlet as a bakery and all-day cafe. The brand has seven outlets across Bali and Jakarta, and this one''s page describes freshly baked artisan pastries, specialty coffee and international dishes. Tables book online; GoFood and GrabFood deliver.'),
    ('adda-yoga', '03a1ef1736b752ad4ea9697528ff8b04', 'A yoga studio above the Awan co-working space on Jalan Kayu Manis in Canggu. Classes run from vinyasa and ashtanga to hatha, yin and restorative, with pranayama and meditation alongside sound healing and kundalini. The studio also runs 200- and 300-hour teacher trainings.'),
    ('amo-spa-canggu-canggu', '58a29e7100e24a36eb079c6858e7c1d9', 'A Batu Bolong wellness spa, open since 2008, that pairs traditional Balinese treatments with AMO Baths. The baths are a self-guided recovery circuit: sauna, ice bath and mineral soak. There are clinical facials too, and a cold-pressed juice cafe.'),
    ('ashe-grill-and-bar', '1836c6294674eb003334830c6573249c', 'Ashe runs a wood-fired grill and bar on Jl. Pantai Pererenan, open evenings only. It opened in December 2025 with a kitchen built, by its own account, around live fire and Global South cooking traditions. The name is a Yoruba concept meaning life force.'),
    ('aunty-ji-s', 'bc3e197de2a2946bc74b24702966893d', 'Aunty Ji''s, a Mumbai-inspired Indian kitchen on Batu Bolong, cooks from family aunty recipes. Expect curries, biryani, naan and street food such as vada pav. It stays open to midnight and delivers through GoFood and GrabFood.'),
    ('baked-berawa', 'ae17af7c7f0d59619acfadb8bfc8c897', 'One of several BAKED. bakehouses in Bali, this one on Jl. Raya Semat in Berawa (Tibubeneng) pairs artisanal baking with specialty coffee. The brand''s site lists gourmet breads and laminated pastries for breakfast, brunch and lunch.'),
    ('baked-pererenan', '9671897f1fd6f08aa012f419e262f0c4', 'The Pererenan branch of BAKED., an artisanal bakehouse and specialty-coffee brand with several locations around Bali. It is on Jl. Pantai Pererenan, and its website describes gourmet breads and laminated pastries from breakfast through brunch to lunch.'),
    ('bali-barber-canggu', 'a00f0b37a17be817eed926bf2174548b', 'The Canggu branch of the Bali Barber chain, a barber for men. It does scissor cuts, clipper fades, beard work and classic hot-towel shaves.'),
    ('bali-buda-canggu', '8370907c4de279769a0d59be7cf9ac22', 'Bali Buda has been on the island for over 25 years; its Canggu branch is an organic wholefoods cafe and shop. The menu covers breakfasts, bowls, salads and mains, plus bakery items and a list of juices and smoothies.'),
    ('bali-mma-canggu', '391da8f84715f9456f0539261be0b14d', 'On Jalan Raya Padonan, Bali MMA runs a combat-sports gym for all levels, kids classes included. Boxing, Muay Thai, BJJ, no-gi grappling and MMA sparring run daily: 6am-10pm on weekdays, 7am-6pm at weekends. There''s a weight room, an ice bath and a sauna.'),
    ('bar-vera-bistro-and-wine-bar', '149eb1637b65f819ce2e03ddff71bcd1', 'A 65-seat European bistro and wine bar on Jl. Pantai Pererenan, cooking produce-driven food with classic technique. The wine list is European-focused, cocktails and aperitifs have their own card, and lunch runs to breakfast plates and coffee. Bookings go through SevenRooms on the venue''s site.'),
    ('beach-boy-canggu', 'a21b8ed49fd8d44ce05c1d601f3a3a46', 'A restaurant and cocktail bar on Jl. Munduk Catu seating up to 132 across five indoor and outdoor areas, rooftop included. The kitchen does steaks, seafood and pasta, with a vegan list; the cocktail and mocktail list is long. Happy hour (4-7pm daily): buy two cocktails, get one free.'),
    ('beachtown-grocer', '1e1cef99eda65e4cdc6f1307a831aa44', U&'Beachtown Grocer is a New York deli-style caf\00E9 and grocery counter inside Secana Beachtown in Berawa, open 6am to 11pm. The daily special rotates and costs 99K. Sit indoors or alfresco, or take breakfast and groceries to go.'),
    ('billy-ho-japanese-restaurant', 'ae6456641f6b927f4b47752acce6376b', 'Billy Ho pairs a modern Japanese kitchen with a cocktail bar on Batu Bolong, open through a long run from lunch to dinner. Yakitori, sushi and shareable plates make up the menu, the cocktails get hand-carved ice, and DJs play at weekends.'),
    ('body-factory-bali-canggu', '8510ba96981bf2a7c3019d921cd815e1', 'At Jl. Nelayan No.27, Body Factory''s large gym opens 6am-10pm daily. More than 50 classes cover HYROX, strength, boxing, mat pilates, mobility and yoga. Recovery runs from hot tub and sauna to ice bath and cold plunge, with a pool too.'),
    ('body-factory-bali-recovery-canggu', '032c57bd46723bc9225bd28daabed2da', 'The recovery wing of Body Factory in Nelayan, open 6am to 10pm. Ice baths, sauna and bodywork here are aimed at recovery after training.'),
    ('bonito-restaurant', 'f10a3d8f8124b80ec1e4cca848b12f6b', 'Bonito is a seafood and Mediterranean kitchen on the roof of the Kleo Hotel in Kerobokan Kelod, run by the team behind MAURI Seminyak. Pasta is handmade and seafood comes in fresh daily. Thursday is an all-you-can-eat oyster-and-pasta night.'),
    ('bottega-italiana', 'da05c056ba09170e4d7d777d50a4b6e1', 'Gourmet Italian home-cooking from the Zibiru group (running since 2015), making its own fresh pasta, bread, cheese and desserts.'),
    ('brother-gym', 'ac72d4dc4bdf1d7d561f45d8f7f872b1', 'Weights and machines fill Brother Gym at Jl. Raya Babakan No.14, open 6.30am-10pm daily. Day passes are sold, and so are weekly, monthly and annual memberships. Its counter adds protein shakes and scoops of supplements to the juice and coffee.'),
    ('brunch-club-pererenan', '96a2aeb80d9b9eb237a4539c570c8bbb', 'Brunch Club Bali''s Pererenan branch on Jl. Pantai Pererenan does brunch, lunch and cocktails all day. The group also has a Legian site. The house dish is Porncakes, a stacked pancake sold as a two- or three-stack in 14 flavours.'),
    ('cafe-del-mar-bali', '72d275c5195a68474ed6a02a51bcd6cd', U&'Caf\00E9 del Mar''s Bali site, a beachfront club on Jl. Subak Sari in Tibubeneng, has an infinity pool, DJ sets and events. The kitchen calls itself premium casual dining from the Mediterranean Basin. Its desserts and cocktails are house creations. Open daily, 11:00 to 20:00.'),
    ('canggu-club-tennis-centre', '27b47af4b53b621fd7ac610265cb9e5a', 'The tennis centre of FINNS Recreation Club, formerly the Canggu Club, on Jl. Pantai Berawa. It has three indoor floodlit courts on a Flexipave surface, plus a pro shop, cafe and bar. Coaches and hitting partners are on hand, ball boys too.'),
    ('canggu-yoga-centre-canggu', '558b59b564d45d2f4a1d47bff799f5e7', 'From early morning, Canggu Yoga Centre teaches Ashtanga, hot yoga and hot-pilates-style HIIT at its Pererenan studio. Showers and a cafe are on site, as is gear. The published timetable shifts, so check the day''s classes before you go.'),
    ('chow-chow-bali', 'a597ece8f9fbf283c5c5ecc36eaf6a5e', 'Chow Chow Bali is a contemporary Asian-fusion restaurant in Batu Bolong, open daily from late morning to midnight. The menu runs to sushi rolls, bao buns, slow-cooked pork ribs and poke bowls. Cocktails and a kids menu round it out.'),
    ('como-beach-club-canggu', '58fd06f5169b7726feb89d3e655ca13f', 'The beach club and restaurant at COMO Uma Canggu, on the sand at Batu Mejan. It runs from breakfast to a 10pm dinner close with live music and DJ sets. Separate menus cover the main kitchen, a seafood BBQ and the COMO Shambhala Kitchen.'),
    ('como-uma-canggu-wellness-spa-canggu', '3bb2b08e96bc2d46e83e942da4043a53', 'Near Echo Beach, COMO Uma Canggu keeps its spa and wellness floor, the COMO Shambhala Retreat, open 10am to 7pm. Massages and body therapies share the menu with Sundari and Guinot facials and nail care. Yoga, Pilates, meditation and breathwork are booked as private sessions.'),
    ('copenhagen-cafe-berawa', '649a80753688e7dcbfc276300bc75677', U&'A Nordic-inspired cafe and bakery in Berawa, built around a build-your-own feast: small dishes ticked off a menu card and served on a board. Sm\00F8rrebr\00F8d, lunch bowls and house-baked pastries fill out the menu. Feasts run 6am-6pm, and lunch starts at 12pm.'),
    ('crate-cafe', 'ff323b4112f06fcd77450571b64e60a0', 'An industrial-style all-day breakfast place on Jl. Batu Bolong. The smoothie bowls are big, and the menu rotates, chalked on the wall behind the counter.'),
    ('cutiepai-nails', '8d6b16516191b4624dbafab079557065', 'CutiePai Nails is a home-based nail salon in Pererenan, minutes from central Canggu, open daily 9am-7pm by appointment. It specialises in BIAB, gel nails, extensions, manicures, pedicures and custom hand-painted nail art, and sanitises tools between clients. Home visits are an option too.'),
    ('dandelion', '707838d2ac961755f7047f61016e3b87', 'Casa Tua, an Indonesian restaurant on Batu Bolong, has cooked Balinese family recipes since 2014. The plant-filled room splits between open-air tables and cosy indoor nooks, and resident rabbits roam free. It used to trade as Dandelion; the team and menu have not changed.'),
    ('desa-seni-yoga', '53013360873414920356588e4f5449ec', 'Daily classes in an open-air wooden shala make up the yoga programme of Desa Seni, a village-style resort near Berawa.'),
    ('deus-ex-machina', '29a767ac2c301da388e11557dd713294', 'On Jl. Pantai Batu Mejan, Deus''s flagship "Temple of Enthusiasm" pairs a Pan-Asian cafe and bar with a motorcycle workshop. A retail store, a gallery and a live-music venue share the site, open from morning coffee until late.'),
    ('downtown-kedungu-restaurant-and-bar', 'bcb4d7f3d092dc5c2c8a87e91fada415', 'Downtown Kedungu, a Latin American restaurant and bar at Kedungu beach in Tabanan, sits about twenty minutes up the coast from Canggu. Every day of the week brings a different themed special.'),
    ('e-a-r-t-h-by-ulaman', 'b076b7cce765ba65ac6c07638df5b66f', 'E.A.R.T.H is the bamboo-built restaurant and lounge of the Ulaman Eco Luxury Resort in Buwit, Tabanan. Chef Alvin cooks Balinese and Nusantara food, and Italian, Thai and international dishes too. Set options range from a chef''s selection to a waterfall-deck dinner.'),
    ('ele-restaurant-bar-and-terrace', '3cf57644fce91cd6505157760393260c', 'ELE keeps an all-day restaurant, bar and terrace on Jl. Pantai Batu Bolong in Canggu, serving breakfast through late dinner. It has no website, only a link page, so we have confirmed the format and the address but not the menu.'),
    ('espace-spa-canggu-canggu', '41330877cedf4f61aaf8fed1f2319152', 'Espace Spa, a day spa on Jl. Pura Batu Mejan near Batu Bolong, publishes its price list. It covers aromatherapy massage, body scrubs, wraps, facials, cream bath, manicures, pedicures and sugaring hair removal. It also runs private massage classes and sells massage tables and chairs.'),
    ('estetica-belle', '3cba3d2422ae4b24ed793dd8cf21d363', 'Estetica Belle works from a beauty studio at Jl. Pantai Pererenan No.69. It does lashes, brows, nails, waxing, permanent make-up, skin needling and laser tattoo removal. Clinical facials use Dermalogica and Doctor Babor products, plus Mesoestetic. The skin-treatment price list is on its own site.'),
    ('f45-training-canggu-canggu', 'd09614c3c52dbaff879735ea7e19d7b8', 'The Canggu studio of the global F45 franchise, at Jl. Pantai Batu Bolong No.83, running 45-minute classes. Its ClassPass schedule puts cardio on Mondays and Wednesdays and resistance on Tuesdays, Thursdays and Sundays. Fridays and Saturdays are hybrid sessions.'),
    ('face-therapy-spa-pererenan', '43c64671df1f9035645b79eafe15cb35', 'Face Therapy, a face-massage spa on Jl. Tukad Pingai in Pererenan, opens 8am to 10pm daily. Treatments cover gua sha, buccal sculpting, lymphatic work and jetlag recovery. Its Fresha listing says woman-owned and kid- and pet-friendly, and names a second branch in Umalas.'),
    ('finns-beach-club', 'c41da63da6630bb9314a9a6fb5aff12c', 'On a 170m stretch of Berawa beachfront, FINNS Beach Club is a day club with three pools, including swim-up bars. There are many bars and kitchens, and a daily lineup of DJs and live vocalists. It is the high-energy, pool-party end of Canggu''s beach clubs.'),
    ('finns-recreation-club-finns-lifestyle-village', '742d0f48cbc9fb73e9d68b47dd547d5d', 'FINNS Recreation Club is the large membership club at FINNS Lifestyle Village in Berawa. It has a full gym, an Olympic-sized pool, tennis and padel courts and a kids'' club. Recovery means ice baths and an infrared sauna plus compression therapy; the spa is full-service Balinese.'),
    ('fitness-plus-canggu', '8aa2b10b995b693f4a6abfc7f5815449', 'Fitness Plus Canggu, part of the Indonesian Fitness Plus chain, runs a 24-hour gym at Jl. Tanah Barak No.19. Its branch site lists more than 100 machines. The eight group programmes are Les Mills BodyPump, RPM, BodyCombat and Ceremony; Positive Spin; Mat Pilates; yoga; and Zumba.'),
    ('flex-gym-bali', '1b5c71ff7b05828e9511183d8b9584ba', 'Flex Gym has a single location: a gym on Gang Heliconia, off Jl. Raya Canggu. Strength equipment, from squat racks to machines, shares the floor with treadmills, rowers and air bikes. Passes run from a single day to twelve months. It has lockers and changing rooms, and parking.'),
    ('genius-bistro', '13eb178208b2e4b40b75bd7a9d11f39b', 'Among rice fields north of central Canggu, Genius Bistro cooks French, Mediterranean and steakhouse food on Jl. Sempol. About 50 seats split between indoors and al fresco. The kitchen leans French: duck served at the table, braised lamb shank, duck a l''orange. Book through Chope.'),
    ('glo-day-spa-salon-canggu-canggu', 'c7bc1221241797035dca5c0a0962437f', 'One of five Bali branches of Glo Salon & Beauty, which used to trade as Glo Day Spa & Salon. It sits at Jl. Subak Sari 90, opposite Popular supermarket. It covers hair, facials, nails, waxing, threading, lash and brow, spray tanning and makeup.'),
    ('goldust-beauty-facials-canggu', 'e546aff2f118ff1790b88bfac820d543', 'The facial and beauty side of Goldust, a Canggu day spa. Its treatments are results-focused, the Express Lifting Facial among them.'),
    ('goldust-spa-canggu', 'eecfe8f1be3bf28f283e089857b59868', 'Goldust Spa is a day spa on Gg. Nyepi, off Jl. Pantai Batu Bolong. Under one roof are massage suites, a poolside lounge, a nail lounge and a couple''s room. The list runs from 30-minute poolside massages to 24k Gold facials and two-and-a-half-hour couple''s packages.'),
    ('gravity-stretching-canggu', '8abd593c271fc5c8d26a45284a418433', 'A stretching studio built on suspended ropes: the exercises are done in relaxation rather than tension, so gravity takes the load off the muscles. The Bali operation has studios in Canggu and Ubud, with group classes, private Gravity Therapy sessions and a children''s class.'),
    ('green-spot-cafe', '5208d219595a9ed4144b7314fccb9db5', 'Green Spot, the cafe of Ecosfera Hotel at Echo Beach, serves an all-day international menu of breakfasts, burgers, bowls and grills. Its menu page lists breakfast from 35K and lunch mains up to 115K, plus weekly deals like a Wednesday burger-and-drink and Sunday two-for-one smoothies.'),
    ('guan-yin-yoga-canggu', '08a749d5c9fc457da78d762d500f7af3', 'Guan Yin has its yoga shala on the upper floor of Hotel Tugu Bali, on Jl. Pantai Batu Bolong at Canggu Beach. The published timetable runs Vinyasa, Yin, Hatha Flow, Ashtanga, Kundalini, Qigong, gentle Pilates and guided meditation. Non-guests can walk in.'),
    ('home-by-chef-wayan', '5bbb70d0e816efe146fca20e8a7def97', 'Near the beach on Jl. Pantai Pererenan, Chef Wayan Kresna Yasa runs HOME, a modern Balinese restaurant. The kitchen reworks family and island recipes with contemporary technique. Vegan dishes are marked on every course, next to sate, seafood and traditional mains.'),
    ('indigo', '97fca5dcc64b0bdbdcb3a268780c8412', 'Indigo has served Japanese food in Berawa since 2017 under Kyoto-trained chef Morita Shigehiko. There is a sushi and sashimi selection, and yakimono cooked over charcoal. The room is small and deliberately plain, with shoji-style doors, timeworn teak and indigo denim cushions.'),
    ('isla-by-earth-island', 'f723b9c202fa02abe185653bc226d8c1', 'ISLA, the all-day cafe at Earth Island''s surf shop, sits at Jl. Subak Canggu No.77 on the Canggu shortcut. The menu goes from breakfast and coffee through seafood snacks and grilled mains to cocktails. The site calls it a space for events, music, art and film.'),
    ('ju-bali', '5d840ce6ffb38544ec96261e9e18b8ca', 'Ju Bali is a casual Umalas restaurant with a jacuzzi club. International comfort food with a Balinese turn: pasta, burgers and wood-fired pizza. Vegetarian and vegan plates include tandoori cauliflower and mushroom tagliatelle. Its 200 seats come with a kids menu and parking for cars and scooters.'),
    ('jungle-padel-canggu-canggu', 'e5f09aec03f1f2a05fa47e68eb5d6e28', 'Jungle Padel runs padel courts in Canggu, open early until late for court hire and social games.'),
    ('jungle-padel-canggu-shortcut', 'bb9ea100016bfb003e78a6935b52393a', U&'A padel club on the Canggu shortcut, with panoramic glass-walled courts among tropical greenery. Courts are booked by the hour on the Jungle Padel app. Racket hire, coaching, a pro shop, changing rooms and an on-site caf\00E9 are all there.'),
    ('kecambah-restaurant-at-lalasa-villas', '3e2dcb04cf8f353a27a8e0c66a20e27d', 'Lalasa Villas on Pantai Berawa has Kecambah as its street-front restaurant, a casual room open from breakfast until late. The cooking leans Indonesian, with Western dishes too. There is a Balinese rijsttafel evening, and afternoon tea is booked ahead.'),
    ('la-brisa-bali', '362f7ee9a2273c5a72f76ea1f7feff99', 'La Brisa is a rustic beach club on Echo Beach, hand-built from wood salvaged from old Indonesian fishing boats. It has a saltwater pool, a raw and oyster bar and wood-fired Mediterranean food. Expect a driftwood look and long, open sunset views over the surf break.'),
    ('loop-cafe', '1d03290a7954622163043b4c674448d5', 'Eggs, salmon, chicken, cottage cheese, Greek yoghurt, oats and sourdough make up the menu at LOOP, a high-protein breakfast cafe in Pererenan. Six protein shakes are made for after training. Specialty coffee and smoothie bowls share the menu with wraps and vegan options.'),
    ('lowcal-cheatery-and-bar', '62130113ad39bdc0e9ecf2dfdc3308cd', 'LowCal, on Jalan Pantai Batu Bolong, builds a low-calorie menu that also covers paleolithic and ketogenic eating. It trains and employs deaf team members across kitchen, bar and service roles. Dinner choices include chicken, pork, fish and vegetarian dishes, with low-carb sides.'),
    ('lulu-bistrot', '65b45c5b5e70aa099a1a61550540d1d0', 'On Jl. Pantai Batu Bolong, Lulu Bistrot cooks classic French bistro dishes with local, seasonal ingredients. The room and bar take their cue from the grand cafes. It opens in the evenings, with an early happy hour.'),
    ('luma', '11eb8d5a534084981b921bb115ca10fa', 'An intimate, 30-seat open-air spot on Batu Bolong, Luma cooks rustic Mediterranean small plates. The chefs are Cameron Emirali, of 10 Greek Street in London, and Kieran Morland, of Merah Putih and Sangsaka. Beer and cocktails are on tap; vinyl DJs play at weekends.'),
    ('lyma-beach', 'c72c9ee54df309c1ad5d99492f60420a', 'Lyma Beach is a beachfront bar and restaurant on Pantai Lima, where the river meets the ocean. Expect sunset views, cocktails and live entertainment through the week.'),
    ('manhattan-cocktail-hookah-kitchen', 'b7a42ca5bb0b60a4b6091efccc276d42', 'Manhattan puts shisha service and a kitchen alongside a cocktail bar on Jl. Pantai Batu Bolong. It publishes no website beyond a link page, and its menu is not readable online. We can confirm the format, the address and WhatsApp booking.'),
    ('mason', '551af63788b4639ec749c058f2ad0d39', 'Trading as MASONRY., Mason runs a moody, minimalist grill on Batu Bolong. The cooking is wood-fired and leans Mediterranean, the charcuterie is made in-house, and there is a wine and cocktail list.'),
    ('mia-asian-modern-inspired-restaurant-and-bar', '68f1a2cb9f43bcc848dd21d8c690bac4', 'Off Jl. Raya Semat, MiA is a modern Asian restaurant and bar built around sharing. Sushi rolls, raw plates, curries, wok and grill dishes make up the menu, and it runs into the early hours at weekends.'),
    ('miel-specialty-coffee-canggu', '0a8b322bd6911e446480260e22b21c06', 'MIEL is a specialty-coffee cafe on Batu Bolong with a brew bar for V60, pour-over and cold brew. The space is bright and plant-filled, with high ceilings. Spacious tables and fast wifi in a quiet room make it a work spot too.'),
    ('milk-and-madu-berawa', '58ddeaf6f45794040939b2631511b8bf', 'The Berawa flagship of Milk & Madu, an all-day Canggu cafe brand. It does hearty brunch, lava-stone pizzas and family-friendly dinners.'),
    ('milu-by-nook', '26c46601ef7f6a16361608b7a98ea203', 'Milu by Nook, a restaurant on Jl. Pantai Berawa, has a garden looking over a small rice paddy. It serves Balinese-Western dishes and coffee from morning until night.'),
    ('mission-flow-studio', 'd303872841a1357858091adc1de1310d', 'Minutes from the sea in Pererenan, Mission Flow Studio is a light-filled space for yoga and conscious movement, with panoramic windows. Classes cover Vinyasa flow, Yin and Restorative, taught by a rotating roster of experienced teachers.'),
    ('moana-fish-eatery', 'f25385ca84ca2e64961ac9265aba4c3e', 'Moana, a Tahitian-Polynesian fish eatery on Jl. Pantai Batu Bolong, opens from morning until late. The fresh seafood runs to poke bowls, sashimi, carpaccio, tartare and BBQ fish.'),
    ('mosto-berawa', '8370cde8d0efda7bc3b5cec6afe79188', 'Mosto is a neo-bistro in Berawa. The room seats around 60, and the list runs to more than 70 natural-wine labels from small producers. Food is ingredient-focused, and it opens evenings only.'),
    ('murmur-restaurant-lounge', '5a69f7cb7607f1a7467187463fd325c3', 'Murmur is a two-storey all-day restaurant and lounge on Jl. Anggrek, with over a hundred seats and a VIP room for eleven. Tables look over the rice fields at sunset. Breakfast runs to 4pm before the dinner menu starts, and the room stays open to 2am.'),
    ('nail-lesss-canggu', 'af3ae97702a7b07401bdef6bb23f06e7', 'At Nail Lesss, a nail salon on Jalan Pantai Pererenan, the work is manicures, gel and acrylic extensions and classic eyelash extensions.'),
    ('neighbourhood-food-berawa', '6f41fc04465c2bf003960a967592bcc1', 'Neighbourhood Food''s Berawa cafe and coffee shop, on Jl. Pantai Berawa, keeps daytime hours. It serves slow breakfasts, snacks and simple wholesome dishes made from local produce.'),
    ('neighbourhood-food-seseh', '5b3bb3df6f1cb766ff71888bc022d48c', 'Among the Seseh fields, Neighbourhood Food has a local eatery and coffee shop. It serves slow breakfasts, afternoon snacks and weekend dinners, with fresh, simple dishes from local produce.'),
    ('nirvana-strength-tibubeneng', '421b664241ac91bf8b5bc293c2e57885', 'Nirvana Strength, a wellness club on Jl. Pantai Berawa, runs more than 100 classes a week across strength, yoga, pilates, mobility, breathwork and sound. Recovery means ice baths, saunas, steam rooms, hot tubs and pools.'),
    ('nude-berawa', 'a682cb0be07c16167661fbb2d63863d8', U&'At a busy junction on Jl. Pantai Berawa, N\00DCDE runs a healthy cafe, part of a small Bali group. From breakfast to evening it serves wholesome bowls, salads, wraps, smoothies and coffee.'),
    ('only-nails-pererenan', 'e3206d9492f4b4bebd79a70820e803ff', 'The Russian manicure technique and long-wear gel are the speciality at Only Nails, a nail salon on Jl. Raya Tiyingtutul in Pererenan. A 4-hands service does manicure and pedicure at once, and the space is calm.'),
    ('paed-thai-canggu', '70d213e7a8d9c24e2fa2a87f629a1505', 'Part of the Wonderspace group, Paed Thai cooks Thai food on Jl. Canggu Padang Linjong. The menu has tom yum goong, pad thai, green curry and mango sticky rice. Indoor and outdoor tables face rice fields.'),
    ('pizza-fabbrica', 'dfad6bdce053a0bd4f23355b52c82eee', 'Pizza Fabbrica is a Neapolitan pizzeria on Jl. Batu Mejan, with a second branch in Umalas. The pizzas are wood-fired, thin and light, the pasta is fresh, and the room is industrial in style.'),
    ('poule-de-luxe-bali', 'fe98d41029666809927a175996924d83', 'Poule de Luxe makes cream puffs, macarons, tarts and viennoiserie in its French patisserie and bakery on Jl. Batu Belig. You can eat in or take away. It also supplies desserts to villas and restaurants, and for parties.'),
    ('revolver-canggu', '75d72f429d93aa26401e8411a16369fc', 'Revolver, a Bali coffee brand founded in 2012, roasts its own beans; this is its all-day cafe on Jl. Nelayan in Canggu. Espresso and full brunch run by day, heavier plates in the evening, and it turns bar-ish after dark.'),
    ('rise-and-shine-cafe', '5e14d3eaa3a4f28a2e1d77c43ad980bd', 'Open since 2017 on Jl. Padang Linjong, Rise and Shine is a colourful all-day breakfast and lunch cafe. It serves fresh, health-conscious comfort food with coffee and juices, all in the open air.'),
    ('rite-bali', 'facb4483f63439abfcc631c66ec3ccc0', U&'RITE Bali, a wellness club on Jl. Pantai Pererenan, has a gym, yoga classes and a recovery zone. Recovery pairs a sauna and steam room with a jacuzzi and a 7-9\00B0C cold plunge. A 500k day pass bundles recovery with gym access.'),
    ('rite-bali-recovery-canggu', '94e6ad5b5f6a541d4cce9ee67b0cb965', 'The recovery-and-spa side of RITE Bali in Pererenan. Sauna, ice bath and bodywork come bundled with gym access on a 500k day pass.'),
    ('rite-bali-yoga-canggu', '5b91e55d35eede24c03c4caaf3033a67', 'The yoga strand of RITE Bali in Pererenan, with classes alongside the club''s gym and recovery facilities.'),
    ('riviera-bistro-berawa', '6a5ef91e1a622776db33dfd48a42cfa7', 'Riviera Bistro, open since 2020, is a modern Mediterranean bistro and wine bar in Berawa with whitewashed arches. The wine list is extensive, Aperitivo hour runs daily, and Saturday is DJ night. It opens from late morning until late.'),
    ('riviera-cafe-cemagi', 'd3ec6082fa013592f5d180f6e38644d5', 'Riviera Group''s garden cafe in quiet Cemagi leans Mediterranean-Italian, with cozy interiors and greenery. Live acoustic music plays on Saturday evenings.'),
    ('riviera-trattoria-pererenan', '0e25d6b694cde963e13f6f3fc8f3c83a', 'The Riviera Group''s Italian trattoria in Pererenan does hand-rolled pastas and Neapolitan pizzas, with an extensive wine and cocktail list. The room is cozy and lively.'),
    ('rize-cafe', '81864d6ac9fe67fbb83a78c1add7c5b5', 'Spices are ground daily at Rize, a Pererenan cafe serving contemporary Indian home cooking rooted in family recipes. Brunch classics, craft cocktails and house chai fill out the menu.'),
    ('ruko-cafe', '89c5330610f4caa6af826073f72242fc', 'About 300m from Berawa beach, Ruko is an Australian-style neighbourhood cafe for breakfast and brunch. The food is healthy and locally sourced, 40-50% of the produce is local and organic, and the coffee is its own Indonesian blend.'),
    ('sa-mesa-canggu-experience-dining', 'd980e6552aae7f7ae53a1e4ccbacc64f', 'One long communal table is the centre of Sa''Mesa, an Italian restaurant in Canggu open since early 2021. There is no menu: guests share a set procession of roughly 14-18 dishes that changes daily. Plates like tuna crudo, grilled octopus and house fettuccine go down the middle.'),
    ('sama-sama-prime', '68ac2d2cb80917a163c88c058bd8c3fb', 'Sama Sama Prime, from the Sama Sama group, combines a steakhouse and a sushi bar on Jl. Raya Semat. Its own site calls it a steakhouse sushi bar on the homepage and a modern premium Japanese restaurant on the about page. We have not settled which.'),
    ('samadi-bali', '062cd51ff5337eaa688ced058262d406', 'Samadi is a yoga and wellness hub on Jl. Padang Linjong, in the Batu Bolong part of Canggu. Its organic vegetarian cafe is certified by the Slow Food movement and serves superfood bowls and traditional Indian dishes.'),
    ('samesa-canggu', 'e091477cc4724922e650cef3efb54f3c', 'A communal Italian dinner where everyone shares one long table. The multi-course set menu is family-style, inspired by an Italian grandmother''s table. There is one seating, dinner only, and you book ahead.'),
    ('santanera', 'b562f4242df1970cd2e33cd73d47e915', 'On Jl. Tanah Barak, Santanera pairs a Latin American dining room with a rooftop bar. The sharing menu mixes Latin flavours with European technique and local ingredients. Contemporary artwork, a big seated room and a late-night bar make a full evening of it.'),
    ('satu-satu-coffee-company', '32fbff8db43f8dc0b7361ad931c15a19', 'Built on the Sudana family''s Balinese single-origin beans, roasted in-house, Satu-Satu is a family-run specialty coffee company in Berawa. The bright white space is eco-minded. A simple all-day menu of bowls, sandwiches and smoothies feeds the post-surf crowd.'),
    ('saya-club', 'c572bc854f5ebc506656573020ab8fff', 'Saya Club combines a gym and coworking space in Berawa. There is personal training, and classes in pilates, reformer, boxing and yoga. On site are an ice bath, a sauna, a pool and a cafe-bar.'),
    ('secana-rooftop-bali', 'b62719cc2367ea3066f53f75a2f95838', 'On top of the Secana Beachtown resort in Berawa, Secana Rooftop is a pool bar and restaurant open from morning to 11pm. There are daybeds by day, the menu moves between Mediterranean and comfort cooking, and DJs play sunset sessions on Fridays and Sundays.'),
    ('secret-spot-bali', '2eebf1c526ec6c9b2abb301ff479d7b3', 'Secret Spot is a fully plant-based cafe serving vegan food from breakfast through dinner: croissants, bowls, curries and ramen. The coffee is roasted weekly on the island, with chicory as an alternative. Monday is pasta night, with live jazz.'),
    ('seseh-general-store', '4a5b15a4480014608167f5ab64a2b183', 'Melbourne coffee culture comes to coastal Cemagi and Seseh at Seseh General Store, an Aussie-owned corner cafe a short step from the beach. It does well-made breads, sandwiches and salads, and has the feel of a community hub.'),
    ('shelter-restaurant', 'b59910a50580da5b75e907dee657c645', 'Shelter, a wood-fired Middle Eastern and Mediterranean restaurant in Pererenan, is built inside a Balinese joglo with open, plant-filled architecture. A UK chef runs the kitchen, and a rotating calendar brings BBQs and vinyl DJ nights. Booking is recommended.'),
    ('shichirin-japanese-restaurant-canggu', 'cadb67aaac0c915531ff9bc1ab04e126', 'Shichirin brings Japanese grill cooking to Berawa as part of the Wonderspace group. The menu has teppanyaki, gyukatsu and izakaya plates. Sushi and sashimi are on it too. The house dishes are black cod in saikyo miso and breaded Santuri wagyu.'),
    ('shosan-holistic-spa-canggu', 'cae1c0a3af84386cf1e98acf936953fd', 'Shosan, a wellness spa in Canggu, takes bookings through Fresha. Its published list covers head massage and traditional massage, and the 90-minute Shosan Signature Massage costs 1100K IDR.'),
    ('sia-grill-and-seafood-bar', '54aa43b82fcb0a0df61795418028f551', 'SIA is a casual seafood and grill bar on the Canggu Shortcut. Fresh fish meets Balinese ingredients and Asian influences, and there is a cocktail programme.'),
    ('skool-kitchen', '52acf3989a62356f5595b8dc9408aafe', U&'SKOOL Kitchen is an open-flame kitchen on Jl. Pura Dalem that cooks meats and seafood over wood and charcoal. Dinner only, from 5pm: a tasting menu, \00E0 la carte plates and cuts priced by weight. It shares an address with The Lawn Canggu, another Project Black venue.'),
    ('smoke-grill-master-and-barbeque-bali', 'ce13a0797753fa012042b41371fd695e', 'SMOKE cooks open-fire barbecue at Echo Beach, with seating outdoors, in a tent or indoors. It also has a private backyard barn and a chef''s table, for groups of ten or more booked 48 hours ahead.'),
    ('spring-spa-canggu', '685e8aaf4ea8b3405f87a9b91ba13a45', U&'Spring Spa''s Batu Bolong branch belongs to an island-wide chain and sits a short walk from Canggu''s caf\00E9s. It does brisk, well-priced manicures, waxing, massage and facials in a bright, clean salon.'),
    ('surya-fitness-gym', '8ba6e7e7fb803e75458247fead0a83b5', 'A gym and fight club in Pererenan, Surya Fitness uses Life Fitness, Hammer Strength and TechnoGym equipment. The fight club runs boxing, Muay Thai, pad work and sparring. On site are a stretching rooftop and a cafe, plus billiards.'),
    ('sushimi-bali', 'd6a12431c0eea1dbf76d55d853e8e398', 'On Jl. Pantai Berawa, Sushimi''s sushi train carries classic and creative sushi and maki, plus an izakaya-style a la carte range. The menu extends to poke bowls, donburi, sushi burritos and sushi donuts. There are gluten-free, vegan and vegetarian options.'),
    ('swarna-spa-and-wellness', 'e9a35d2e235a0832a20ed2d93280e64f', 'Swarna does Balinese and hot stone massage and facials at its spa and wellness venue in Pererenan. Its house thermal ritual combines a hot plunge and cold immersion with an infrared sauna.'),
    ('the-avocado-factory', '850dbc3188405ed4970a49a816da67ac', 'Avocado runs through the whole menu at The Avocado Factory, a cafe. Dishes run from truffle eggs benedict to avo pancakes and avocado basque cheesecake, in an eco-conscious build.'),
    ('the-canggu-studio-yoga-canggu', '434c7a743289b7cb438d6d590ffa701d', U&'The yoga-and-mat side of The Canggu Studio, with small-group classes on a clean Mon\2013Sat timetable (drop-in 170k).'),
    ('the-flow-bali', '29f3b09ea337b8968d4230fab749722e', 'The Flow Bali is a char-grill restaurant in Pererenan cooking modern plates with Mediterranean and Asian influences. The menu runs from croquettas and carpaccio up to prime cuts on the wood fire.'),
    ('the-lawn-canggu-beach-club', '21966e776e78fbb95585d190abcab89d', 'Right on the black sand of Batu Bolong Beach, The Lawn is a beach club with an ocean-facing infinity pool and daybeds. Its bar-restaurant runs sunset sessions with DJs over the Indian Ocean, as daytime lounging shifts into golden-hour drinks.'),
    ('the-loft-bali', '007ddce0fdf69879652fc2177be1e2d4', 'The Loft serves specialty coffee and a large plant-based selection at its Bondi-inspired all-day brunch cafe on Batu Bolong. The food leans to healthy breakfast staples, bowls and toasts.'),
    ('the-shady-shack', 'a8eab9256db1db9a3d7e5b6c4697ac2e', 'From the team behind Betelnut, The Shady Shack is an all-day vegetarian and vegan cafe looking over the Berawa rice fields. The wholefood menu is big: all-day breakfast, smoothies, salads, share plates and vegan desserts, in a leafy, open setting.'),
    ('the-shampoo-lounge-canggu', 'bc15e5d7fe24a7a69b200ca03ca6e709', 'HairShop is the Canggu branch of a Bali hair-salon brand, in Tegal Gundul Square on Jl. Pantai Berawa. English-speaking stylists do cuts, colour and blow-outs in an air-conditioned space.'),
    ('the-slow', '558d9f147c87222dfe978f4631908d98', 'The restaurant, bar and gallery inside The Slow, a design-led boutique hotel on Batu Bolong. The kitchen is internationally inspired and runs all day, and the room doubles as an art and events space. It works for breakfast as well as an evening out.'),
    ('therapy-canggu-canggu', '0ea53ed24580e2127cf4aa5754cbfaf6', 'The Batu Bolong flagship of the Therapy group, open 9am to 8pm, with massage, facials and beauty treatments in a calm space.'),
    ('therapy-day-spa-pererenan', 'd85ba22f0ea43e51abe82052a0e59fe9', 'Therapy Day Spa on Jl. Pantai Pererenan is built around plant-derived rituals that are toxin-free and cruelty-free. Massages, facials, body scrubs and scalp treatments run in a calm setting.'),
    ('therapy-hair-spa-canggu-canggu', '93a2d14c3cb76e06fc1f9beb6e8c5123', 'The Therapy group''s Canggu salon, open 9am to 8pm, pairs hairdressing with spa-style facials and massage. On the hair side there are cuts, colour and blow-outs.'),
    ('top-gym', 'c8fb7310c043b2082831862d7ee8003e', 'A 400-square-metre boutique gym near Batu Bolong, Top Gym has rice field views and TechnoGym equipment throughout. The recovery area has a panoramic terrace, two ice baths, a sauna, a smoothie bar and loungers.'),
    ('touche-cafe-and-restaurant', 'cc2af8425c3d3ee9df78ee7bd411ff38', U&'Near Pererenan beach, Touch\00E9 keeps all-day cafe hours from early morning to late, with design-led interiors and an urban-leaning menu.'),
    ('tropical-nomad', 'd00e83ac72caefe087142f58918a42a1', 'Tropical Nomad is a coworking space on the Canggu shortcut with an open-air cafe built in that looks over rice fields and a garden. It is made for eating, sitting with a laptop and staying a while.'),
    ('two-face-canggu', '0b637d1fa79cb7675205a6b30d262b30', 'Well-made coffee and creative brunch dishes are the focus at TWO FACE, a specialty coffee and brunch cafe on Jl. Munduk Catu in Canggu. It has a community feel.'),
    ('udara-bali', '8f8d3866d7f9a29d217fa5942add074c', 'Organic Ocean, the plant-forward restaurant at the Udara wellness retreat in Seseh, is open daily to guests and visitors. The cooking is healthy and conscious of community and earth.'),
    ('udara-bali-yoga-detox-and-spa-organic-ocean', 'c1863e93420d1dc1e6d4919339920b44', 'At Seseh Beach, Udara Bali is a yoga, detox and wellness retreat resort for adults only (14+). It has five ocean-view yoga shalas and Quantum Sound Domes for sound healing. Its spa has a water-healing pool; there are seawater pools too, and the plant-forward Organic Ocean restaurant.'),
    ('ulekan-berawa', '63229d20ccb8d94ff5f2e061bdee93ff', 'Ulekan, a sit-down Indonesian restaurant in Berawa, cooks dishes from across the archipelago. Spices are ground by hand and there is no MSG or palm oil; ingredients come from small-scale farmers and fishermen. Tables sit in a fairy-lit garden.'),
    ('victory-fitness-club', '5d8089b61f7fc5e3be2803a40b4ad972', 'Open daily 07:00-20:30, Victory Fitness Club is a budget gym at Jl. Pantai Pererenan No.89. Equipment spreads over two floors, with a punching bag and loan gloves upstairs and a smoothie bar below. An ice bath and sauna are on site.'),
    ('warung-local', '066d58c79a301f6c39abb683e2be6f08', 'Warung Local is a semi-open Indonesian warung on the Batu Bolong strip, open daily 10am to 10pm. The kitchen is Halal and cooks local staples such as nasi campur, nasi goreng and satay, and there is an outdoor seating section.'),
    ('warung-nonii', '96727fc2c12d7c4f06037b696bfef5ca', 'Just up from the beach on Jl. Pantai Batu Bolong sits Warung Nonii, also written Waroeng Nonii, an affordable Indonesian warung. It is open from breakfast through dinner, nasi campur is the house plate, and takeaway is available.'),
    ('warung-sika', 'ffa4840e6e03d3dedf71ddd9c6e9383a', 'Family-run Warung Sika serves nasi campur, open daily 9am to 9pm. It is point-and-pick: you choose rice, then add vegetables and meats from the display.'),
    ('woods-bali', 'b199265737704d441f3bf733e2e069df', 'Built entirely from reclaimed wood, Woods is a rustic Pererenan restaurant cooking a Mediterranean menu in a warm, greenery-filled chalet. It runs as a cafe by day and a dinner room by night, with live jazz and vinyl evenings.'),
    ('workmates-coworking-space-and-cafe', '41e8a3913c435bae4bf0f0b03055a004', 'Workmates is a coworking space and cafe in Canggu, part of the Wonderspace group. Desks and fast wifi come with a poolside view. The kitchen does chicken parmigiana, Indonesian plates and bowls.'),
    ('wrong-gym-pererenan', '1d0cf61ddb39fd558bc43c3568a78e36', 'Opened in 2023 on Jl. Pantai Pererenan, The Wrong Gym is an all-inclusive gym and lifestyle club. It has a large outdoor training area, a functional jungle gym and fitness classes. Recovery means sauna, ice bath, pool, yoga and spa.'),
    ('yema-kitchen', '9b77fa55e071147e3fea33a22bc1897e', U&'A caf\00E9 and restaurant on Jl. Tanah Barak, Yema Kitchen runs as a caf\00E9 by day and a bar by night. It calls itself Mediterranean but cooks closer to North African and Levantine: tajine, couscous, pastilla, shawarma and pide.'),
    ('yuki-canggu', 'fcc30c136a8e4c4c695a6dd990312a7b', 'Steps from Batu Bolong beach, YUKI is a modern Japanese izakaya. It serves fusion sushi, wood-fired specialties and house cocktails.'),
    ('zin-cafe-canggu', 'f868d329af8a0a5d0aa06a6bbf5b7017', 'ZIN is an open-air bamboo cafe near Nelayan Beach that doubles as a free coworking space. Most tables have power outlets, the wifi is fast and there is a quiet upper room. The coffee is organic and roasted in-house.')
  ) as d(slug, old_md5, val)
  where v.slug = d.slug and v.status = 'active' and v.publication_status = 'published'
    and case when d.old_md5 is null then (v.why_its_here is null or length(trim(v.why_its_here)) = 0) else md5(v.why_its_here) = d.old_md5 end;
  get diagnostics n = row_count; if n <> 141 then raise exception 'wave-canggu-2026-10-08 why_its_here: expected 141 rows, got %', n; end if;

  update venues v set best_for = d.val
  from (values
    ('adda-yoga', 'a5893be9f21ba048769d9ac29020116f', 'A walk-in class, with drop-in rates tiered by tourist visa, KITAS or Indonesian ID'),
    ('amo-spa-canggu-canggu', '3db6483456414f228e0d327c3a73953e', 'A slow, personalized massage or facial, or the hot-cold AMO Baths circuit'),
    ('ashe-grill-and-bar', 'b0ca21f0fa761deebe68310c5d5bc5f2', 'Late dinners of wood-fired grill cooking on the Pererenan beach road'),
    ('aunty-ji-s', '50b0469beb2fe61c71f4fa358abc6f0c', 'A craving for Indian comfort food, from curries and biryani to vada pav, or a weekend brunch'),
    ('baked-berawa', 'e859f000cd54cc6adce27ef0bd4548c9', 'A morning meet-up over brunch, coffee and pastries'),
    ('baked-pererenan', '5c12c2ac85234663b364789772f7ab0d', 'Morning brunch, or a pastry-and-coffee stop on the Pererenan beach road'),
    ('bali-barber-canggu', '33eb0613e22bd4c23ac669d65f60079a', 'Men after a walk-in cut, fade or shave in central Canggu'),
    ('bali-buda-canggu', '3e4b9aad690a3809427272fa74c9caa0', 'A wholefoods brunch or lunch with vegan, gluten-free and paleo options marked, then a raid on the organic shop'),
    ('bali-mma-canggu', '03e5f273fe7dde3b85a6850b3b595364', 'A fight-training session at any level on a day pass, from 240K'),
    ('bar-vera-bistro-and-wine-bar', '4fff2b48b8d7493cadec7cecf01c5641', 'European wine and bistro plates over a date night or late dinner'),
    ('beach-boy-canggu', '7481c670cfd7c25ceacefeeeefc5d8b2', 'A date night, a group dinner or a birthday, with live acoustic sessions on Saturdays'),
    ('beachtown-grocer', '88dd53c1e44d6ca390688eea673c480e', 'A deli breakfast or the 99K daily special, with groceries to grab on the way out'),
    ('billy-ho-japanese-restaurant', 'dcd033d2da135b3c7d716bef962059dc', 'Japanese small plates and cocktails over a long lunch that rolls into dinner'),
    ('body-factory-bali-canggu', '28108ac1d717a738ea5e039a0337458e', 'A gym or HYROX session on a 1, 3, 7 or 14-day pass or a four-week membership'),
    ('body-factory-bali-recovery-canggu', 'e0363b6ae94264a5ee0c83d091e44efd', 'After training, when you want cold plunge and sauna rather than a traditional spa'),
    ('bonito-restaurant', 'c498eb5a30c726ca7501856e2ab621c0', 'A rooftop dinner of Mediterranean seafood and pasta, shared or as a tasting menu'),
    ('bottega-italiana', 'b9be4104f83d7417141cf2a931c259ee', 'Families and groups sharing pasta'),
    ('brother-gym', 'c0c2399e4bacbc8447a99bbf343c1c3f', 'A low-cost weights session on a day pass, with personal training by the session or in packs'),
    ('brunch-club-pererenan', 'b795b8e51f08b762a26f30c4bbc5f632', 'Friends or family over an all-day brunch of big sweet and savoury plates, with cocktails'),
    ('cafe-del-mar-bali', '8212e685059f822f4fd6c7e8589bef4e', 'Sunset drinks or a pool day, Ibiza-style, with a group after the beach'),
    ('canggu-club-tennis-centre', '1dd5921ecfac40105a47847d587a166f', 'Tennis out of the sun on a floodlit court, on a day pass or a membership open to the public'),
    ('canggu-yoga-centre-canggu', '98d27d58360b3407eb70c2b8a0dfa24d', 'An accessible morning practice in Pererenan: Ashtanga, hot yoga or hot pilates'),
    ('chow-chow-bali', 'a668bdde0fde93cca10be72221ccefcb', 'From lunch to late night: Asian-fusion sushi, bao and poke bowls in Batu Bolong'),
    ('como-beach-club-canggu', 'eb03c49e65b45125d922d549343cd4b4', 'A polished sunset dinner or special occasion by the ocean, or a leisurely family-style Sunday brunch at 680K per person'),
    ('como-uma-canggu-wellness-spa-canggu', '159bfe0df7899410d954088178be42fe', 'A 75-90 minute massage or a facial at a resort spa, or a private yoga or Pilates session'),
    ('copenhagen-cafe-berawa', '2ef29154c89a670185ac18106927d619', 'Build-your-own Nordic breakfast boards from 6am, or daytime brunch and coffee'),
    ('crate-cafe', '3208521b02e8751571f68bd395b10b5a', 'An affordable all-day brunch on Batu Bolong, straight after a surf'),
    ('cutiepai-nails', '705527cc0bfea596afbfd75cbf19bac7', 'A booked BIAB, gel or nail-art session in a small, private Pererenan setting'),
    ('dandelion', '2b460542773b25110feb1f792f282c87', 'Balinese home cooking over a romantic meal among plants, with resident rabbits'),
    ('desa-seni-yoga', '38db78fb61a002f687cc56cdec8b02cd', U&'A drop-in class in a garden setting, then a meal at the resort''s organic caf\00E9'),
    ('deus-ex-machina', '7fb6f1cb8b98495311942233a3741344', 'Coffee and brunch by day, or a night of live music with a crowd'),
    ('downtown-kedungu-restaurant-and-bar', '60df0f598b491cb94ee6ba2db59245a0', 'A trip up the coast for Latin American plates and the day''s themed special'),
    ('e-a-r-t-h-by-ulaman', 'f7ef3f73c45bbad7f0c4934956939875', 'Balinese or Nusantara meals at the Ulaman eco resort, among jungle, river and waterfalls'),
    ('ecosfera-yoga-canggu-canggu', '6dad4856f56f3edab67f308dd668cb77', 'A yoga class by the water, near Batu Mejan and Echo Beach'),
    ('ele-restaurant-bar-and-terrace', '988daf76ec20abd214f4c9bc01616d75', 'Any meal from breakfast to a late dinner on Batu Bolong'),
    ('espace-spa-canggu-canggu', '8d8659636b921bc85442f58d6db013d1', 'A fixed-price massage, scrub, facial or nail treatment booked online in Batu Bolong'),
    ('estetica-belle', '6e564a947bed3d49b80e28cf57a1dedd', 'Lashes, brows, nails, waxing and clinical facials in one Pererenan studio'),
    ('f45-training-canggu-canggu', '5e4fea7c3e86f8f1cc24ce562d2af597', 'A coached 45-minute class mixing HIIT, circuit and functional training'),
    ('face-therapy-spa-pererenan', '1b0eed3b7fa1020879a3e2b1f5686854', 'Gua sha and buccal sculpting, or a jetlag-recovery face treatment after a long flight'),
    ('finns-beach-club', '8e3cb2fc100a6da37b54ae7dbde836e9', 'A lively, high-energy pool day and sunset party with a big group'),
    ('finns-recreation-club-finns-lifestyle-village', '9ae91bc8fb4ab524d5344613c70ab03d', 'Families and active travellers on a longer Canggu or Berawa stay, on a day pass or a membership'),
    ('fitness-plus-canggu', 'a56cb11408c656f08ca08b62a18834b4', 'A workout at any hour, with a sauna, lockers, showers, towels and parking on site'),
